import serial
import time

class SerialBus:
    def __init__(self, port, baudrate):
        self.serial = serial.Serial(port, baudrate, timeout=0)

    def send_request_frame(self, address, request_type):
        # Add code to send the request frame
        # and wait for the response
        self.serial.write(b'\x10' + address.to_bytes(1, byteorder='big') + b'\x00' + request_type.to_bytes(1, byteorder='big'))
        time.sleep(0.1)  # Add a small delay
        return self.serial.read(5)

    def close(self):
        self.serial.close()

